import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BwzYn71E.js";const f=JSON.parse('{"title":"仓库相关优先级现象","description":"","frontmatter":{"translationSource":{"title":"仓库相关优先级现象","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pgnaI2HtL8UdrJqoloJQvA","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/depot-related-priority-phenomena"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/depot-related-priority-phenomena"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/depot-related-priority-phenomena"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/depot-related-priority-phenomena"}]]},"headers":[],"relativePath":"zh/depot-related-priority-phenomena.md","filePath":"zh/page-pgnaI2HtL8UdrJqoloJQvA.md"}'),d={name:"zh/depot-related-priority-phenomena.md"};function i(l,e,n,p,s,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><h1 id="仓库相关优先级现象" tabindex="-1">仓库相关优先级现象 <a class="header-anchor" href="#仓库相关优先级现象" aria-label="Permalink to &quot;仓库相关优先级现象&quot;">​</a></h1><blockquote><p>源页面 ID：<code>pgnaI2HtL8UdrJqoloJQvA</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pgnaI2HtL8UdrJqoloJQvA" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-d5922f12e457a433.q90-04b897c52e14153c.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-fd14ff7c64c73e3f.q90-e2565d9429a53c5e.webp" alt="图片"></td></tr></tbody></table><p>该结构中，将两个仓库取货口AB与其中一个A连接的传送带重放，会使得A优先。</p><p>单独重放存货口可能使其进入低优先状态，但是无法稳定达到，无法确定结果与所需次数，也就是基本上是随机的出现优先级问题。</p><p>经测试，该现象（取货口优先级）几乎总是会在下线后被修正，通常可以忽略，然而无法稳定该结论，甚至有时下线反而会引发该问题</p><p>不确定反应池是否有类似现象（取货口优先级）。</p><p>仓库存货口存在与反应池相同的优先输入现象，具体为先连接先输入。</p><p>此外协议核心亦有相同现象（取货口优先级、存货口优先级），该现象可能是稳定的。</p></div>',1)])])}const g=t(d,[["render",i]]);export{f as __pageData,g as default};
